function addReaction(node, dest){
  if(!node || !dest) return;
  node.reactions = node.reactions || [];
  // avoid duplicates
  if(node.reactions.some(r=>r.action && r.action.destinationId===dest.id)) return;
  node.reactions.push({
    trigger:{type:'ON_CLICK'},
    action:{type:'NODE', destinationId:dest.id, navigation:'NAVIGATE', transition:{type:'SMART_ANIMATE'}}
  });
}

