function wire(node, dest){
  if(!node || !dest) return;
  const existing = node.reactions||[];
  const merged = existing.filter(r=>!(r.action && r.action.destinationId===dest.id));
  const reac = makeReaction(dest);
  // setter property
  (node).reactions = [...merged.filter(()=>false)];
  // use simple assignment of a new array including new one (runtime allows setter)
  node.reactions = [...existing, reac];
}

