function desc(n){
  let out=[];
  if(n.children&&n.children.length){
    n.children.forEach(c=>{
      if(c.reactions&&c.reactions.length){
        out.push({name:c.name, id:c.id, reactions:c.reactions.map(r=>({trig:r.trigger, act:r.actions?r.actions.map(a=>({type:a.type,dest:a.destinationId})):r.action}))});
      }
      const sub=desc(c);
      if(sub.length) out=out.concat(sub.map(s=>({name:c.name+' > '+s.name, id:s.id, reactions:s.reactions})));
    });
  }
  return out;
}
