(function scan(n,path){
  if(n.reactions && n.reactions.length){
    count+=n.reactions.length;
    details.push(path+' ['+n.name+']: '+n.reactions.map(r=>{
      const a=r.actions?r.actions:r.action?[r.action]:[];
      return a.map(x=>x.type+(x.destinationId?('->'+x.destinationId):'')).join(',');
    }).join(' | '));
  }
  if(n.children) n.children.forEach(c=>scan(c,path+'/'+n.name));
})(page,'');
