const page=figma.getNodeById('4:2');
const F=n=>page.children.find(f=>f.name===n);
function find(frame, name){
  let stack=[frame];
  while(stack.length){
    const n=stack.pop();
    if(n.name===name) return n;
    if(n.children) n.children.forEach(c=>stack.push(c));
  }
  return null;
}
function links(frame){
  const arr=[];
  (function scan(n){
    if(n.reactions) n.reactions.forEach(r=>{
      const acts=r.actions?r.actions:(r.action?[r.action]:[]);
      acts.forEach(a=>{ if(a.type==='NODE') arr.push(a.destinationId); });
    });
    if(n.children) n.children.forEach(scan);
  })(frame);
  return arr;
}
function hasLink(frame, dest){
  const fr=F(frame), did=F(dest)?.id;
  if(!fr) return frame+' NOFRAME';
  if(!did) return dest+' NODEST';
  return links(fr).includes(did)? null : frame+'->'+dest;
}
